      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n<text x=\"550\" y=\"68\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"32\" font-weight=\"bold\">KNOWLEDGE CHECK</text>\n<rect x=\"150\" y=\"130\" width=\"800\" height=\"190\" rx=\"16\" fill=\"#6366f1\" stroke=\"#6366f1\" stroke-width=\"2\" opacity=\"0.1\"/>\n<text x=\"550\" y=\"195\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"22\" font-weight=\"bold\">THE CRISIS CONVINCER MECHANISM</text>\n<text x=\"550\" y=\"240\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\" font-weight=\"normal\">Bypasses doubt, produces real proof</text>\n<text x=\"550\" y=\"278\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\" font-weight=\"normal\">Not adrenaline or fear alone</text>\n<rect x=\"200\" y=\"470\" width=\"700\" height=\"100\" rx=\"16\" fill=\"#ffd700\" stroke=\"#ffd700\" stroke-width=\"2\" opacity=\"0.1\"/>\n<text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\" font-weight=\"bold\">Proof beats persuasion</text>\n<text x=\"550\" y=\"550\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\" font-weight=\"normal\">Evidence updates self-image fastest</text>\n</svg>",
