      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n<text x=\"550\" y=\"68\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"32\" font-weight=\"bold\">KNOWLEDGE CHECK</text>\n<rect x=\"150\" y=\"130\" width=\"800\" height=\"190\" rx=\"16\" fill=\"#6366f1\" stroke=\"#6366f1\" stroke-width=\"2\" opacity=\"0.1\"/>\n<text x=\"550\" y=\"195\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"22\" font-weight=\"bold\">REHEARSE, THEN ACT</text>\n<text x=\"550\" y=\"240\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\" font-weight=\"normal\">Preparation happens before</text>\n<text x=\"550\" y=\"278\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\" font-weight=\"normal\">Execution trusts the trained image</text>\n<rect x=\"200\" y=\"470\" width=\"700\" height=\"110\" rx=\"16\" fill=\"#10b981\" stroke=\"#10b981\" stroke-width=\"2\" opacity=\"0.1\"/>\n<text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\" font-weight=\"normal\">Rehearse (before)  →  Act (release, no monitoring)</text>\n<text x=\"550\" y=\"550\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\" font-weight=\"normal\">Never collapse the two together</text>\n</svg>",
